import random


def is_prime(n: int, k: int = 20) -> bool:
    """Miller-Rabin primality test.

    Args:
        n: The number to test for primality.
        k: Number of rounds (witnesses) to test. Higher = more reliable.

    Returns:
        True if n is probably prime, False if n is composite.
        Deterministic for all n < 3,317,044,064,679,887,385,961,981 when k=20.
    """
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as 2^r * d where d is odd
    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    # Witness loop
    for _ in range(k):
        a = random.randrange(2, n - 1)
        x = pow(a, d, n)

        if x == 1 or x == n - 1:
            continue

        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False

    return True


if __name__ == "__main__":
    # Quick demo
    test_values = [1, 2, 3, 4, 17, 561, 1105, 294409, 6601, 104729]
    for v in test_values:
        print(f"{v:>10} -> {'prime' if is_prime(v) else 'composite'}")
